import React, { useEffect, useState } from "react";
import "../styles/subscriptions.css";

const BASE_URL = "http://127.0.0.1:8000";

function Subscriptions() {
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState(null);
  const [content, setContent] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const token = localStorage.getItem("token");

  // Завантаження каналів
  useEffect(() => {
    const fetchChannels = async () => {
      try {
        const res = await fetch(`${BASE_URL}/api/channels/`, {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        });
        if (!res.ok) throw new Error("Помилка завантаження каналів");
        const data = await res.json();
        setChannels(Array.isArray(data) ? data : data.results || []);
      } catch (err) {
        setError(err.message);
      }
    };
    fetchChannels();
  }, [token]);

  // Відкрити канал (завантажити статті + опитування)
  const openChannel = async (channelId) => {
    setSelectedChannel(channelId);
    setLoading(true);
    setError(null);

    try {
      const [aRes, pRes] = await Promise.all([
        fetch(`${BASE_URL}/api/channels/${channelId}/articles/`, {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        }),
        fetch(`${BASE_URL}/api/channels/${channelId}/polls/`, {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        }),
      ]);

      const articlesData = await aRes.json();
      const pollsData = await pRes.json();

      const articles = (articlesData.results || articlesData || []).map((a) => ({
        ...a,
        type: "article",
      }));

      const polls = (pollsData.results || pollsData || []).map((p) => ({
        ...p,
        type: "poll",
      }));

      // Об’єднуємо за часом створення
      const merged = [...articles, ...polls].sort(
        (a, b) => new Date(b.created_at) - new Date(a.created_at)
      );

      setContent(merged);
    } catch (err) {
      setError("Помилка завантаження контенту");
    } finally {
      setLoading(false);
    }
  };

  // Голосування
  const handleVote = async (pollId, choiceId) => {
    const votedPolls = JSON.parse(localStorage.getItem("votedPolls") || "[]");
    if (votedPolls.includes(pollId)) {
      alert("Ви вже голосували в цьому опитуванні!");
      return;
    }

    try {
      const res = await fetch(`${BASE_URL}/api/polls/${pollId}/vote/${choiceId}/`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(token && { Authorization: `Bearer ${token}` }),
        },
      });

      if (!res.ok) throw new Error("Помилка голосування");

      // Оновлюємо голоси локально
      setContent((prev) =>
        prev.map((item) =>
          item.id === pollId
            ? {
                ...item,
                choices: item.choices.map((c) =>
                  c.id === choiceId ? { ...c, votes: (c.votes || 0) + 1 } : c
                ),
              }
            : item
        )
      );

      localStorage.setItem("votedPolls", JSON.stringify([...votedPolls, pollId]));
    } catch (err) {
      console.error(err);
      setError("Не вдалося проголосувати");
    }
  };

  // Повернення до списку каналів
  const backToChannels = () => {
    setSelectedChannel(null);
    setContent([]);
  };

  return (
    <div className="subscriptions-container">
      <h2>📡 Підписки</h2>

      {error && <p className="error">{error}</p>}

      {!selectedChannel ? (
        <>
          {channels.length === 0 ? (
            <p>Поки немає каналів</p>
          ) : (
            <ul className="channel-list">
              {channels.map((ch) => (
                <li key={ch.id} className="channel-item">
                  <span className="channel-name" onClick={() => openChannel(ch.id)}>
                    {ch.name || "Без назви"}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </>
      ) : (
        <div className="channel-content">
          <button className="back-btn" onClick={backToChannels}>
            ← Назад
          </button>

          {loading ? (
            <p>Завантаження...</p>
          ) : content.length === 0 ? (
            <p>Контент відсутній</p>
          ) : (
            <div className="content-list">
              {content.map((item) =>
                item.type === "article" ? (
                  <div key={`article-${item.id}`} className="article-card">
                    {item.image && (
                      <img
                        src={
                          item.image.startsWith("http")
                            ? item.image
                            : `${BASE_URL}${item.image}`
                        }
                        alt={item.title}
                        className="article-image"
                      />
                    )}
                    <div className="article-body">
                      <h3>{item.title}</h3>
                      <p>{item.content || "(Без контенту)"}</p>
                      <small>
                        Опубліковано:{" "}
                        {new Date(item.created_at).toLocaleDateString("uk-UA")}
                      </small>
                    </div>
                  </div>
                ) : (
                  <div key={`poll-${item.id}`} className="poll-card">
                    <h3>🗳️ {item.question}</h3>
                    <div className="poll-choices">
                      {item.choices?.length > 0 ? (
                        item.choices.map((c) => (
                          <div key={c.id} className="choice-item">
                            <button
                              className="vote-btn"
                              onClick={() => handleVote(item.id, c.id)}
                            >
                              Проголосувати
                            </button>
                            <span className="choice-text">
                              {c.text} — <b>{c.votes || 0}</b> голосів
                            </span>
                          </div>
                        ))
                      ) : (
                        <p>Немає варіантів</p>
                      )}
                    </div>
                  </div>
                )
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default Subscriptions;
